import { Meta, StoryObj } from "@storybook/react";
import Banner, { BannerProps, HeadingLevel, ThemingType, arrowPositions, headingLevels, themingTypes } from "./banner";
import { action } from "storybook/actions";
import { ShowcaseLayout, Variant, showcaseParameters } from "../../../../.storybook/preview";

const meta = {
  title: "Primitives/Banner",
  component: Banner,
  argTypes: {
    onButtonClick: { table: { disable: true } },
    id: { table: { disable: true } },
    type: {
      control: "select",
      options: themingTypes,
      defaultValue: "information" as ThemingType,
    },
    headingLevel: {
      control: "select",
      options: headingLevels,
      defaultValue: "h2" as HeadingLevel,
    },
    arrow: {
      control: "select",
      options: [undefined, "top", "bottom", "left", "right"] as typeof arrowPositions & undefined,
    },
    buttonText: {
      control: "text",
    },
    onClose: {
      control: "boolean",
      mapping: { true: () => action("Close button clicked"), false: undefined },
    },
  },
  render: (args) => {
    const handleClose = args.onClose ? () => action("Close button clicked")() : undefined;
    const handleButtonClick =
      args.buttonText && args.buttonText.length > 0 ? () => action("Button clicked")() : undefined;
    return <Banner {...args} onClose={handleClose} onButtonClick={handleButtonClick} />;
  },
} satisfies Meta<typeof Banner>;

export default meta;

type Story = StoryObj<typeof meta>;

